// Setup application logging identity and options
openlog("ServiceName", LOG_PID | LOG_NDELAY, LOG_LOCAL0);

// Log message with variables (Priority: LOG_NOTICE)
syslog(LOG_NOTICE, "Configuration loaded successfully from %s", path);

// Error logging (Priority: LOG_ERR)
syslog(LOG_ERR, "Failed to start thread %d: %s", thread_id, strerror(errno));

// Critical failure (Priority: LOG_CRIT)
syslog(LOG_CRIT, "Service shutting down due to unrecoverable error.");

// Facility examples: LOG_DAEMON, LOG_USER, LOG_MAIL, LOG_LOCAL0..7

closelog();
